'use client';

import * as React from 'react';
import { motion, type Variants } from 'motion/react';

import {
  getVariants,
  useAnimateIconContext,
  IconWrapper,
  type IconProps,
} from '@animate-ui/react/icons';

type Maximize01Props = IconProps<keyof typeof animations>;

const animations = {
  default: {
    frame: {},
    arrow1: {
      initial: { x: 0, y: 0, transition: { duration: 0.3, ease: 'easeInOut' } },
      animate: {
        x: 0.8,
        y: -0.8,
        transition: { duration: 0.3, ease: 'easeInOut' },
      },
    },
    arrow2: {
      initial: { x: 0, y: 0, transition: { duration: 0.3, ease: 'easeInOut' } },
      animate: {
        x: -0.8,
        y: 0.8,
        transition: { duration: 0.3, ease: 'easeInOut' },
      },
    },
  } satisfies Record<string, Variants>,
  'default-loop': {
    frame: {},
    arrow1: {
      initial: { x: 0, y: 0 },
      animate: {
        x: [0, 0.8, 0],
        y: [0, -0.8, 0],
        transition: { duration: 0.6, ease: 'easeInOut' },
      },
    },
    arrow2: {
      initial: { x: 0, y: 0 },
      animate: {
        x: [0, -0.8, 0],
        y: [0, 0.8, 0],
        transition: { duration: 0.6, ease: 'easeInOut' },
      },
    },
  } satisfies Record<string, Variants>,
} as const;

function IconComponent({ size, ...props }: Maximize01Props) {
  const { controls } = useAnimateIconContext();
  const variants = getVariants(animations);

  return (
    <motion.svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={2}
      {...props}
    >
      <motion.path
        d="M19.9264 22.2516V20.691C19.9264 20.288 20.0525 19.8966 20.2639 19.5531C21.7583 17.1245 22.2279 14.5196 21.9002 13.505C20.857 11.3418 17.3758 10.4907 15.76 10.2878L16.7966 5.12292C16.9705 4.30387 16.3513 3.47938 15.4135 3.28136C14.4758 3.08334 13.5746 3.58679 13.4007 4.40583L11.3462 14.0815L8.77462 12.4424C8.77462 12.4424 7.47969 11.406 6.44041 12.4424C5.40114 13.4788 6.44041 14.7701 6.44041 14.7701L10.3488 19.7776C10.6003 20.0997 10.7468 20.4908 10.7688 20.8984L10.8401 22.2177"
        strokeLinecap="round"
        strokeLinejoin="round"
        variants={variants.frame}
        initial="initial"
        animate={controls}
      />
      <motion.path
        d="M7.32936 1.85194C7.32936 1.85194 9.54861 1.58797 9.867 1.90156C10.1124 2.14335 9.867 4.36134 9.867 4.36134M9.867 1.90156L6.89808 4.84002"
        strokeLinecap="round"
        strokeLinejoin="round"
        variants={variants.arrow1}
        initial="initial"
        animate={controls}
      />
      <motion.path
        d="M4.6477 9.59694C4.6477 9.59694 2.42845 9.86092 2.11005 9.54732C1.86463 9.30553 2.11005 7.08754 2.11005 7.08754M2.11005 9.54732L5.07898 6.60886"
        strokeLinecap="round"
        strokeLinejoin="round"
        variants={variants.arrow2}
        initial="initial"
        animate={controls}
      />
    </motion.svg>
  );
}

function Maximize01(props: Maximize01Props) {
  return <IconWrapper icon={IconComponent} {...props} />;
}

export {
  animations,
  Maximize01,
  Maximize01 as Maximize01Icon,
  type Maximize01Props,
  type Maximize01Props as Maximize01IconProps,
};
